using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class MarinaPolishSync{const string D="Assets/Scenes/Oasis/YachtPortAtlas";static MarinaPolishSync(){EditorApplication.update+=Poll;}static void Replace(Transform t){foreach(var c in t.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(c.gameObject);PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Marina Existing City Props Features.prefab"),t);}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaPolishSync.request"))return;File.Delete("MarinaPolishSync.request");try{var feature=PrefabUtility.LoadPrefabContents(D+"/Marina Existing City Props Features.prefab");foreach(var t in feature.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("Cargo containers")||t.name.StartsWith("Harbour operations office")).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);PrefabUtility.SaveAsPrefabAsset(feature,D+"/Marina Existing City Props Features.prefab");PrefabUtility.UnloadPrefabContents(feature);foreach(string path in new[]{"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",D+"/Yatch_Port Existing City Props.prefab"}){var p=PrefabUtility.LoadPrefabContents(path);var t=p.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port"||f.gameObject==p).transform;Replace(t);PrefabUtility.SaveAsPrefabAsset(p,path);PrefabUtility.UnloadPrefabContents(p);}var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var y=s.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");Replace(y.transform);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();File.AppendAllText("FinalEnvironmentRoadReview/MarinaReferencePolish.txt","\nScene and road/standalone prefabs synchronized; cargo objects remaining="+y.GetComponentsInChildren<Transform>().Count(t=>t.name.Contains("Cargo containers")));}catch(Exception e){File.AppendAllText("FinalEnvironmentRoadReview/MarinaReferencePolish.txt",e.ToString());}}}

